 function orderLayers(){const entries=[...installed.values()];for(const entry of entries)map.moveLayer(entry.layers[0]);for(const entry of entries.filter(e=>e.level===2))map.moveLayer(entry.layers[1]);for(const entry of entries.filter(e=>e.level===1))map.moveLayer(entry.layers[1]);for(const entry of entries)map.moveLayer(entry.layers[2]);}
