 return{bounds:home,warm,sync,setMode,updateLabels,pauseLabels:clearLabels,context(){},get ready(){return ready;},get active(){return active;},getSelection:()=>selected?.id||null,restore:async id=>{if(index.has(id))await select(index.get(id),false);},async enter(fit=true){await warm();active=true;sidebar.hidden=false;await reset(fit);sync();scheduleDetails();},leave(){generation++;detailGeneration++;selectionEpoch++;active=false;sidebar.hidden=true;clearTimeout(detailTimer);cancelWorker();warming=null;desired=[];budget.clear();clearHover();clearLabels();for(const key of [...installed.keys()])removeSource(key);ready=false;selected=null;document.getElementById('mode-lock').hidden=false;},home:()=>reset(),viewParent:()=>selected?.parent?select(index.get(selected.parent)):reset(),random(){const list=catalogue.records.filter(p=>p.level===mode);select(list[Math.floor(Math.random()*list.length)]);}};
